package com.medcore.backend.api.auditoria;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class AuditoriaService{private final AuditoriaRepository repository;public AuditoriaService(AuditoriaRepository repository){this.repository=repository;}@Transactional public void registrar(String usuario,String accion,String entidad,Long entidadId,String detalle){Auditoria a=new Auditoria();a.setUsuario(usuario);a.setAccion(accion);a.setEntidad(entidad);a.setEntidadId(entidadId);a.setDetalle(detalle);repository.save(a);}@Transactional(readOnly=true)public Page<AuditoriaResponse>listar(Pageable p){return repository.findAll(p).map(AuditoriaResponse::from);}}
